@php $compact=$compact??false;$title=data_get($item,'title',data_get($item,'name'));$price=(float)data_get($item,'price');$old=(float)data_get($item,'original_price');$src=data_get($item,'image',data_get($item,'image_url',asset('themes/E805/images/tech-sale.png'))); @endphp
<article class="e805-product {{ $compact?'is-compact':'' }}"><a class="e805-product-image" href="{{ data_get($item,'url','#') }}"><img src="{{ $src }}" alt="{{ $title }}">@if($old>0)<span>-{{ max(1,(int)round((1-$price/$old)*100)) }}%</span>@endif</a><div class="e805-product-body"><h3>{{ $title }}</h3><strong>{{ $price>0?number_format($price,0,',','.').'đ':'Liên hệ' }}</strong>@if($old>0)<del>{{ number_format($old,0,',','.') }}đ</del>@endif @unless($compact)<small>Đã bán {{ data_get($item,'sold',62) }}</small><div class="e805-progress"><i style="width:{{ data_get($item,'progress',55) }}%"></i></div>@endunless</div><a class="e805-cart" href="{{ data_get($item,'url','#') }}" aria-label="Thêm vào giỏ"><i class="fa-solid fa-bag-shopping"></i></a></article>
